        noc_async_read(dram_tile_addr, l1_write_addr, tile_size_bytes);
        // Wait for the transfer to complete before making the data visible
        noc_async_read_barrier();
        // Publish the tile to the CB
        cb_push_back(cb_id_in0, 1);
    }
}
